import { T } from "./lib.mjs";
import { H, W, makeEnglish } from "./english-helpers.mjs";

const lessonOf = (grade) => (n, sk, S, title, concept, example, core, challenge) => ({ id: `en-${grade}-l${n}`, title, concept, example, skills: [S[sk]], core, challenge });
const first = (w) => T(`첫 단어: ${w}`, `Từ đầu tiên: ${w}`);

function kit(b, grade, S) {
  const E = makeEnglish(b, grade, S);
  /** Fill-in choice with an optional meaning cue in parentheses. */
  const choose = (sk, n, role, d, fam, sentence, items, correct, hints, expl, cue) => E.mc({
    sk, n, role, d, fam, items, correct, hints, expl, tags: ["grammar"],
    prompt: cue ? T(`빈칸에 알맞은 말을 고르세요: ${sentence} (${cue.ko})`, `Chọn từ thích hợp cho chỗ trống: ${sentence} (${cue.vi})`) : T(`빈칸에 알맞은 말을 고르세요: ${sentence}`, `Chọn từ thích hợp cho chỗ trống: ${sentence}`),
  });
  const ord = (sk, n, role, d, fam, meaning, words, hints, expl) => E.order({ sk, n, role, d, fam, meaning, words, tags: ["grammar"], hints, expl });
  /** A question asked in English ("Which word means ...?"): the instruction around it is localised, the question and the options stay English. */
  const ask = (sk, n, role, d, fam, question, items, hints, expl) => E.mc({
    sk, n, role, d, fam, items, correct: 0, hints, expl, tags: ["vocab"],
    prompt: T(`다음 질문에 알맞은 답을 고르세요: ${question}`, `Chọn đáp án đúng cho câu hỏi sau: ${question}`),
  });
  const meaning = (sk, n, role, d, fam, w, others) => E.mc({
    sk, n, role, d, fam, prompt: T(`'${w.en}'의 뜻은?`, `'${w.en}' nghĩa là gì?`), items: [T(w.ko, w.vi), ...others.map((o) => T(o.ko, o.vi))], correct: 0, audio: w.en, tags: ["vocab"],
    hints: [H.sound, H.first(w.en)], expl: T(`${w.en} = ${w.ko}`, `${w.en} = ${w.vi}`),
  });
  const rewrite = (sk, n, role, d, fam, sentence, instruction, accepted, hints, expl) => E.write({
    sk, n, role, d, fam, type: "short_answer", accepted, tags: ["grammar"], hints, expl,
    prompt: T(`${instruction.ko} ${sentence}`, `${instruction.vi} ${sentence}`),
  });
  const read = (sk, n, role, d, fam, passage, q, items, correct, hintT, expl) => E.mc({
    sk, n, role, d, fam, items, correct, tags: ["reading"], expl,
    prompt: T(`글을 읽고 답하세요. "${passage}" 질문: ${q}`, `Đọc đoạn văn rồi trả lời. "${passage}" Câu hỏi: ${q}`),
    hints: [T("질문의 낱말을 글에서 먼저 찾아보세요.", "Hãy tìm trước trong đoạn văn các từ có trong câu hỏi."), hintT],
  });
  return { ...E, choose, ord, ask, meaning, rewrite, read };
}

