  const g3 = ch("gram", 3, "core", 2, "e5-there", "There ____ three books on the desk.", ["are", "is", "am", "be"], [T("books는 여러 개(복수)예요.", "books là số nhiều."), T("복수에는 There are를 써요.", "Số nhiều dùng There are.")], T("There are three books. = 책이 세 권 있어요.", "There are three books. = Có ba quyển sách."));
  const g4 = ch("gram", 4, "core", 2, "e5-article", "I see ____ elephant.", ["an", "a", "the", "two"], [T("elephant는 모음 소리로 시작해요.", "elephant bắt đầu bằng âm nguyên âm."), T("모음 소리 앞에는 an을 써요.", "Trước âm nguyên âm dùng an.")], T("an elephant = 코끼리 한 마리", "an elephant = một con voi"));
  const g5 = ch("gram", 5, "core", 3, "e5-there", "There ____ a cat under the table.", ["is", "are", "am", "be"], [T("a cat은 한 마리(단수)예요.", "a cat là số ít."), T("단수에는 There is를 써요.", "Số ít dùng There is.")], T("There is a cat. = 고양이가 한 마리 있어요.", "There is a cat. = Có một con mèo."));
  ch("gram", "v1", "variant", 1, "e5-article", "She has ____ orange.", ["an", "a", "the", "two"], [T("orange는 모음 소리로 시작해요.", "orange bắt đầu bằng âm nguyên âm."), T("모음 소리 앞에는 an을 써요.", "Trước âm nguyên âm dùng an.")], T("an orange = 오렌지 한 개", "an orange = một quả cam")); ch("gram", "v2", "variant", 2, "e5-plural", "One watch, two ____ .", ["watches", "watchs", "watch", "watchies"], [T("ch로 끝나는 낱말은 -es를 붙여요.", "Từ kết thúc bằng ch thì thêm -es."), T("watch → watches", "watch → watches")], T("two watches = 시계 두 개", "two watches = hai chiếc đồng hồ"));
  ch("gram", "d2", "diagnostic", 2, undefined, "There ____ two cats in the garden.", ["are", "is", "am", "be"], [T("cats는 여러 마리(복수)예요.", "cats là số nhiều."), T("복수에는 There are를 써요.", "Số nhiều dùng There are.")], T("There are two cats. = 고양이가 두 마리 있어요.", "There are two cats. = Có hai con mèo."));
