  ch("comp", "v1", "variant", 1, "e5-er", "A rabbit is ____ than a turtle.", ["faster", "fast", "fastest", "more fast"], [T("두 동물을 비교할 때는 -er을 붙여요.", "So sánh hai con vật thì thêm -er."), T("than은 '~보다'예요.", "than nghĩa là hơn.")], T("A rabbit is faster. = 토끼가 더 빨라요.", "A rabbit is faster. = Thỏ nhanh hơn.")); ch("comp", "v2", "variant", 2, "e5-est", "She is the ____ student in my class.", ["smartest", "smarter", "smart", "most smart"], [T("'the ... in my class'는 가장 ~한 사람을 말해요.", "'the ... in my class' nói về người nhất."), T("-est를 붙여요.", "Thêm -est.")], T("the smartest student = 가장 똑똑한 학생", "the smartest student = học sinh thông minh nhất"));
  ch("comp", "d1", "diagnostic", 2, undefined, "My brother is ____ than me.", ["older", "old", "oldest", "more old"], [T("두 사람을 비교할 때는 -er을 붙여요.", "So sánh hai người thì thêm -er."), T("than은 '~보다'예요.", "than nghĩa là hơn.")], T("My brother is older than me. = 우리 형은 나보다 나이가 많아요.", "My brother is older than me. = Anh trai mình hơn tuổi mình."));

  const f1 = ch("future", 1, "core", 1, "e5-goingto", "I am ____ to visit Jeju tomorrow.", ["going", "go", "goes", "will"], [T("be going to + 동사원형은 '~할 예정이다'예요.", "be going to + động từ nguyên mẫu nghĩa là sắp/định làm."), T("am 다음에는 going이 와요.", "Sau am là going.")], T("I am going to visit Jeju. = 나는 제주에 갈 예정이에요.", "I am going to visit Jeju. = Mình sắp đi thăm Jeju."));
  const f2 = ch("future", 2, "core", 1, "e5-will", "It will ____ tomorrow.", ["rain", "rains", "rained", "raining"], [T("will 다음에는 동사원형이 와요.", "Sau will là động từ nguyên mẫu."), T("-s나 -ed를 붙이지 않아요.", "Không thêm -s hay -ed.")], T("It will rain tomorrow. = 내일 비가 올 거예요.", "It will rain tomorrow. = Ngày mai trời sẽ mưa."));
