  const f5 = ch("future", 5, "core", 3, "e5-goingto", "What are you going to ____ tomorrow?", ["do", "does", "did", "doing"], [T("going to 다음에는 동사원형이 와요.", "Sau going to là động từ nguyên mẫu."), T("do가 동사원형이에요.", "do là động từ nguyên mẫu.")], T("What are you going to do? = 너는 무엇을 할 거니?", "What are you going to do? = Bạn định làm gì?"));
  ch("future", "v1", "variant", 1, "e5-goingto", "We are ____ to play soccer.", ["going", "go", "goes", "will"], [T("be going to + 동사원형이에요.", "Cấu trúc be going to + động từ nguyên mẫu."), T("are 다음에는 going이 와요.", "Sau are là going.")], T("We are going to play soccer. = 우리는 축구를 할 예정이에요.", "We are going to play soccer. = Chúng mình sắp chơi bóng đá.")); ch("future", "v2", "variant", 2, "e5-will", "He will ____ his homework.", ["do", "does", "did", "doing"], [T("will 다음에는 동사원형이 와요.", "Sau will là động từ nguyên mẫu."), T("do가 동사원형이에요.", "do là động từ nguyên mẫu.")], T("He will do his homework. = 그는 숙제를 할 거예요.", "He will do his homework. = Anh ấy sẽ làm bài tập."));
  ch("future", "d1", "diagnostic", 1, undefined, "I will ____ you tomorrow.", ["call", "calls", "called", "calling"], [T("will 다음에는 동사원형이 와요.", "Sau will là động từ nguyên mẫu."), T("-s나 -ed를 붙이지 않아요.", "Không thêm -s hay -ed.")], T("I will call you tomorrow. = 내일 전화할게요.", "I will call you tomorrow. = Ngày mai mình sẽ gọi cho bạn."));

