  const x1 = ch("transform", 1, "core", 1, "e5-neg", "I like carrots. → I ____ like carrots.", ["don't", "doesn't", "isn't", "not"], [T("주어가 I이고 like는 일반동사예요.", "Chủ ngữ là I và like là động từ thường."), T("don't + 동사원형이에요.", "don't + động từ nguyên mẫu.")], T("I don't like carrots. = 나는 당근을 좋아하지 않아요.", "I don't like carrots. = Mình không thích cà rốt."));
